+     for (const [req, {resolve}] of this.pending) {
+       resolve(this.prepareResponse(req));
+     }
+     this.pending.clear();
+ 
+     return Promise.all(allPending);
+   }
+ 
+   protected abstract prepareResponse(request: T): R;
+ }
