+ function createLoadComponentPropertyAssignment(
+   componentImportPath: string,
+   componentDeclarationName: string,
+   isDefaultExport: boolean,
+ ) {
+   return ts.factory.createPropertyAssignment(
+     'loadComponent',
+     ts.factory.createArrowFunction(
+       undefined,
+       undefined,
+       [],
