+   // Does the decorator have any imports?
+   const decoratorArgs = decoratorCallExpression.arguments[0] as ts.ObjectLiteralExpression;
+   const moduleImports = getImportsProp(decoratorArgs);
+   if (!moduleImports) {
+     return;
+   }
