+ function getDevModeNodeName(tNode: TNode) {
+   if (tNode.type & TNodeType.ElementContainer) {
+     return 'an <ng-container>';
+   } else if (tNode.type & TNodeType.Container) {
+     return 'an <ng-template>';
+   } else {
